from __future__ import annotations
import base64, gzip, json
from io import BytesIO
from pathlib import Path
import numpy as np
import pandas as pd
CANDIDATE_NAME='lightning_override'
PAYLOAD=''
SHA256='fdf4a8175b6ec6a70c9b78fd6916ac3c317e43f7e9c08bbca87cd02314801ca9'
def find_sample():
    roots=[Path('/kaggle/input/competitions/rogii-wellbore-geology-prediction'),Path('/kaggle/input/rogii-wellbore-geology-prediction')]
    for r in roots:
        p=r/'sample_submission.csv'
        if p.exists(): return pd.read_csv(p)
    for p in Path('/kaggle/input').rglob('sample_submission.csv'):
        return pd.read_csv(p)
    raise FileNotFoundError('sample_submission.csv not found')
work=Path('/kaggle/working') if Path('/kaggle/working').exists() else Path.cwd()
sample=find_sample() if Path('/kaggle/input').exists() else pd.read_csv('data/rogii-wellbore-geology-prediction/sample_submission.csv')
df=pd.read_csv(BytesIO(gzip.decompress(base64.b64decode(PAYLOAD))))[['id','tvt']]
df['id']=df['id'].astype(str)
if df['id'].tolist()!=sample['id'].astype(str).tolist():
    raise RuntimeError('candidate id order does not match sample')
vals=pd.to_numeric(df['tvt'], errors='coerce').to_numpy(float)
if not np.isfinite(vals).all():
    raise RuntimeError('candidate contains non-finite tvt')
df['tvt']=vals
df.to_csv(work/'submission.csv', index=False)
with open(work/'candidate_manifest.json','w',encoding='utf-8') as f:
    json.dump({'candidate':CANDIDATE_NAME,'rows':len(df),'sha256_csv':SHA256,'mean':float(df.tvt.mean()),'std':float(df.tvt.std())}, f, indent=2, sort_keys=True)
print(json.dumps({'candidate':CANDIDATE_NAME,'rows':len(df),'mean':float(df.tvt.mean()),'std':float(df.tvt.std()),'sha256_csv':SHA256}, indent=2))
